import React, { useState, useRef, useCallback } from 'react';

interface VirtualListProps {
  itemCount: number;
}

const VirtualList: React.FC<VirtualListProps> = ({ itemCount }) => {
  const [scrollTop, setScrollTop] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);

  const itemHeight = 50;
  const containerHeight = 500;
  const visibleItemsCount = Math.ceil(containerHeight / itemHeight);
  const startIndex = Math.floor(scrollTop / itemHeight);
  const endIndex = Math.min(startIndex + visibleItemsCount, itemCount - 1);

  const handleScroll = useCallback(() => {
    if (containerRef.current) {
      setScrollTop(containerRef.current.scrollTop);
    }
  }, []);

  const visibleItems = [];
  for (let i = startIndex; i <= endIndex; i++) {
    visibleItems.push(
      <div key={i} style={{ height: `${itemHeight}px`, borderBottom: '1px solid #ddd', padding: '10px' }}>
        Item {i}
      </div>
    );
  }

  return (
    <div
      ref={containerRef}
      onScroll={handleScroll}
      style={{ /* Add styles here: border, fixed height, overflow */ }}
    >
      <div style={{ /* Add styles here: background color and calculated total height */ }}>
        {visibleItems}
      </div>
    </div>
  );
};

const sampleItems = Array.from({ length: 1000 }, (_, i) => ({ id: i, text: `Item ${i}` }));

const App = () => {
  return <VirtualList itemCount={sampleItems.length} />;
};

export default App;
